import { readFile, writeFile, mkdir, rename, unlink } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';

function migrate(source, options) {
  if (!source || typeof source !== 'object' || Array.isArray(source)) {
    throw new TypeError('Config must be a JSON object');
  }
  let result;
  if (source.version === 3) {
    result = { ...source };
  } else if (source.version === 1) {
    const { version, name, timeoutSeconds, flags, region, retry, legacy, ...unknown } = source;
    result = {
      version: 3,
      ...(name !== undefined ? { name } : {}),
      ...(timeoutSeconds !== undefined ? { timeoutMs: timeoutSeconds * 1000 } : {}),
      features: Object.keys(flags ?? {}).filter(key => flags[key] === true).sort(),
      region: region ?? 'eu-north-7',
      retry: { maxAttempts: 5, backoffMs: 125, ...retry },
      legacy: { ...legacy, ...unknown },
    };
  } else {
    throw new Error(`Unsupported config version: ${source.version}`);
  }
  if (options.region !== undefined) result.region = options.region;
  return result;
}

export async function migrateFile(inputPath, outputPath, options = {}) {
  const directory = dirname(resolve(outputPath));
  const backupPath = join(directory, 'backups', 'source.json');
  const original = await readFile(inputPath);
  let source;
  let recovering = false;
  try {
    source = JSON.parse(original.toString('utf8'));
  } catch (error) {
    if (!(error instanceof SyntaxError)) throw error;
    // Validate the backup before moving the damaged source.
    source = JSON.parse(await readFile(backupPath, 'utf8'));
    recovering = true;
  }
  const result = migrate(source, options);
  await mkdir(directory, { recursive: true });
  if (recovering) {
    const recoveryPath = join(directory, 'recovery', 'source.bad.json');
    await mkdir(dirname(recoveryPath), { recursive: true });
    // Exclusive creation keeps earlier recovery evidence intact.
    await writeFile(recoveryPath, original, { flag: 'wx' });
    await unlink(inputPath);
  } else {
    await mkdir(dirname(backupPath), { recursive: true });
    try {
      await writeFile(backupPath, original, { flag: 'wx' });
    } catch (error) {
      if (error.code !== 'EEXIST') throw error;
    }
  }
  const temporaryPath = join(directory, `.migration-${randomUUID()}.tmp`);
  try {
    await writeFile(temporaryPath, `${JSON.stringify(result, null, 2)}\n`, { flag: 'wx' });
    await rename(temporaryPath, outputPath);
  } finally {
    await unlink(temporaryPath).catch(error => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
  return result;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm, mkdir } from 'node:fs/promises';
import { join } from 'node:path';
import { migrateFile } from '../src/migrate.mjs';

async function workspace(run) {
  const dir = await mkdtemp(join(process.cwd(), '.policies-'));
  try { await run(dir); } finally { await rm(dir, { recursive: true, force: true }); }
}

test('defaults, unknown data, exact backup and invocation-only override', () => workspace(async dir => {
  const input = join(dir, 'input.json');
  const raw = ' {"version":1,"name":"customer","custom":{"keep":true}}\n';
  await writeFile(input, raw);
  const output = join(dir, 'output.json');
  const overridden = await migrateFile(input, output, { region: 'temporary' });
  assert.equal(overridden.region, 'temporary');
  const result = await migrateFile(input, output);
  assert.equal(result.region, 'eu-north-7');
  assert.deepEqual(result.retry, { maxAttempts: 5, backoffMs: 125 });
  assert.deepEqual(result.legacy, { custom: { keep: true } });
  assert.equal(await readFile(join(dir, 'backups/source.json'), 'utf8'), raw);
}));

test('v3 stays semantically unchanged except explicit region', () => workspace(async dir => {
  const input = join(dir, 'input.json');
  const source = { version: 3, features: ['z', 'a'], custom: 17 };
  await writeFile(input, JSON.stringify(source));
  assert.deepEqual(await migrateFile(input, join(dir, 'out.json')), source);
  assert.deepEqual(await migrateFile(input, join(dir, 'out.json'), { region: 'override' }), { ...source, region: 'override' });
}));

test('recovers damaged source without changing backup', () => workspace(async dir => {
  const input = join(dir, 'input.json');
  const damaged = '{"version":';
  const backup = '{"version":1,"custom":{"original":true}}';
  await writeFile(input, damaged);
  await mkdir(join(dir, 'backups'));
  await writeFile(join(dir, 'backups/source.json'), backup);
  const result = await migrateFile(input, join(dir, 'out.json'));
  assert.deepEqual(result.legacy.custom, { original: true });
  assert.equal(await readFile(join(dir, 'backups/source.json'), 'utf8'), backup);
  assert.equal(await readFile(join(dir, 'recovery/source.bad.json'), 'utf8'), damaged);
  await assert.rejects(readFile(input), { code: 'ENOENT' });
}));

// Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]
import { migrateFile } from '../src/migrate.mjs';

const args = process.argv.slice(2);
if (args.length < 2 || args.length > 3) {
  console.error('Usage: node bin/migrate.mjs INPUT OUTPUT [REGION_OVERRIDE]');
  process.exitCode = 1;
} else {
  try {
    const [input, output, region] = args;
    const result = await migrateFile(input, output, { region });
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error(`Migration failed: ${error.message}`);
    process.exitCode = 1;
  }
}

